<script>
const statusLabels={not_started:'Not updated today',available:'Available',consulting:'Seeing patients',break:'On break',delayed:'Delayed',finished:'Chamber finished'};
async function refreshChambers(){await Promise.all(Array.from(document.querySelectorAll('[data-chamber-live]')).map(async box=>{try{const r=await fetch(box.dataset.chamberLive,{headers:{Accept:'application/json'},cache:'no-store'});if(!r.ok)throw new Error();const s=await r.json();box.querySelector('[data-live-text]').textContent=(statusLabels[s.status]||s.status)+(s.serial?' · '+(s.status==='consulting'?'Current':'Last called')+' serial #'+s.serial:'')+(s.expected_return?' · Expected return '+s.expected_return:'')+(s.note?' · '+s.note:'');box.querySelector('[data-live-time]').textContent='Last doctor update: '+(s.updated_at||'None')+' · Checked '+new Date().toLocaleTimeString('en-GB',{timeZone:'Asia/Dhaka'})+' (Bangladesh). Refreshes every 10 seconds.';}catch(e){box.querySelector('[data-live-text]').textContent='Live status unavailable. Reconnecting…';}}));setTimeout(refreshChambers,10000)}refreshChambers();
</script></body></html>
